+const { useState } = React;
+
+const FAQItem = ({ question, answer, id }) => {
+    const [isOpen, setIsOpen] = useState(false);
+
+    return (
+        <div className="example">
+            <button
+                className="faq-question"
+                onClick={() => setIsOpen(!isOpen)}
+                aria-expanded={isOpen}
+                aria-controls={`faq-answer-${id}`}
+                id={`faq-question-${id}`}
+            >
+                <span>{question}</span>
+                <svg className="icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
+                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
+                </svg>
+            </button>
+            <div
+                className="details"
+                id={`faq-answer-${id}`}
+                role="region"
+                aria-labelledby={`faq-question-${id}`}
+                hidden={!isOpen}
+            >
+                <p>{answer}</p>
+            </div>
+        </div>
+    );
+};
+
+const App = () => {
+    const faqs = [
+        {
+            question: "Why do cats purr?",
+            answer: "Cats often purr when they are happy or relaxed, but they also purr to soothe themselves when they are stressed or in pain. It's a versatile form of communication!"
+        },
+        {
+            question: "Why do cats like boxes?",
+            answer: "Boxes provide a sense of security and safety. In the wild, cats seek out confined spaces to hide from predators and stalk prey. A cardboard box is the perfect modern substitute."
+        },
+        {
+            question: "How long do cats sleep?",
+            answer: "On average, cats sleep for about 12 to 16 hours a day. They are crepuscular, meaning they are most active during dawn and dusk."
+        },
+        {
+            question: "Why do cats have whiskers?",
+            answer: "Whiskers are highly sensitive tactile organs that help cats navigate in the dark, judge the width of openings, and detect changes in air currents."
+        }
+    ];
+
+    return (
+        <div className="faq-container">
+            <h1>Cat FAQ</h1>
+            {faqs.map((faq, index) => (
+                <FAQItem 
+                    key={index} 
+                    id={index} 
+                    question={faq.question} 
+                    answer={faq.answer} 
+                />
+            ))}
+        </div>
+    );
+};
+
+const root = ReactDOM.createRoot(document.getElementById('root'));
+root.render(<App />);
+
')

